import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.DDa4BI30.js";const u=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/performance.md","filePath":"guide/performance.md"}'),o={name:"guide/performance.md"};function s(i,t,n,h,l,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>This page gives the measured cost of sdot: a single power diagram, a whole Newton solve, CPU against GPU, and how both scale with the number of diracs and with the dimension. Every number comes from the scripts in <a href="https://github.com/sdot-team/sdot/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a>. The <a href="#reproducing">Reproducing</a> section gives the commands.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>machine</th><th>hardware</th><th>used for</th></tr></thead><tbody><tr><td><code>1</code></td><td>Xeon W-2145 (8 cores, 8 pinned threads), RTX 2080 Ti (Turing, FP64 at 1/32)</td><td>CPU, 2D GPU</td></tr><tr><td><code>2</code></td><td>RTX A6000 (Ampere, 48 GB, FP64 at 1/64)</td><td>3D GPU, 2D GPU at 1e6</td></tr></tbody></table><p>Protocol:</p><ul><li>A Newton solve starts cold, from the Voronoi diagram (zero weights), tree build included. It stops when <code>max |mass - target| / target &lt;= 1e-6</code>.</li><li>GPU times are for a <strong>jitted</strong> call (JAX). An eager call costs about 0.1 s more.</li><li><code>mixed</code> (the GPU default) runs the float kernel and switches to the double kernel when float precision is no longer enough. The final accuracy is the double one.</li></ul><h2 id="in-short" tabindex="-1">In short <a class="header-anchor" href="#in-short" aria-label="Permalink to &quot;In short&quot;">​</a></h2><table tabindex="0"><thead><tr><th>problem</th><th>n</th><th>CPU (8 threads)</th><th>GPU</th><th>speed-up</th></tr></thead><tbody><tr><td>2D, uniform, Lebesgue</td><td>1e5</td><td>1.02 s</td><td>0.072 s (2080 Ti)</td><td>14x</td></tr><tr><td>2D, clustered (5 lines)</td><td>1e5</td><td>4.0 s</td><td>0.29 s (2080 Ti)</td><td>14x</td></tr><tr><td>2D, uniform, Lebesgue</td><td>1e6</td><td>–</td><td>0.38 s (A6000)</td><td>–</td></tr><tr><td>3D, uniform, Lebesgue</td><td>1e5</td><td>2.29 s</td><td>0.135 s (A6000)</td><td>17x</td></tr><tr><td>3D, clustered (4 planes)</td><td>1e5</td><td>6.67 s</td><td>0.47 s (A6000)</td><td>14x</td></tr><tr><td>2D, 512² image target</td><td>1e5</td><td>29.2 s</td><td>1.88 s (2080 Ti)</td><td>16x</td></tr><tr><td>2D, 4 gaussians (σ = 0.02)</td><td>1e5</td><td>62.7 s</td><td>7.2 s (2080 Ti)</td><td>9x</td></tr></tbody></table><p>The image and gaussian targets include a width continuation (16 to 22 smoothing stages), which explains why they cost more than the Lebesgue cases.</p><h2 id="one-power-diagram" tabindex="-1">One power diagram <a class="header-anchor" href="#one-power-diagram" aria-label="Permalink to &quot;One power diagram&quot;">​</a></h2><p>This is the cost of computing every cell&#39;s measure for fixed weights. It is the inner loop of every solver, measured in nanoseconds per dirac (kernel time only).</p><table tabindex="0"><thead><tr><th>case</th><th>n</th><th>GPU float</th><th>GPU double</th></tr></thead><tbody><tr><td>2D uniform</td><td>1e6</td><td><strong>9.3</strong> (2080 Ti)</td><td>57 (2080 Ti)</td></tr><tr><td>2D lines, Voronoi</td><td>1e5</td><td>25 (2080 Ti)</td><td>80 (2080 Ti)</td></tr><tr><td>2D lines, equal areas</td><td>1e5</td><td>52 (2080 Ti)</td><td>289 (2080 Ti)</td></tr><tr><td>3D uniform</td><td>1e6</td><td><strong>118</strong> (A6000)</td><td>457 (A6000)</td></tr><tr><td>3D planes, Voronoi</td><td>1e5</td><td>128 (A6000)</td><td>451 (A6000)</td></tr><tr><td>3D planes, equal volumes</td><td>1e5</td><td>217 (A6000)</td><td>1190 (A6000)</td></tr></tbody></table><p>So a 2D diagram with one million diracs takes about <strong>10 ms</strong> on a gaming GPU, and a 3D one about <strong>120 ms</strong>.</p><p>In float, the cell measures match the double kernel to a median relative error of 1e-14 in 2D (max 1e-8). In 3D the median error is 0 and the maximum 7e-5. The <code>mixed</code> mode then finishes the solve in double.</p><h2 id="scaling-with-the-number-of-diracs" tabindex="-1">Scaling with the number of diracs <a class="header-anchor" href="#scaling-with-the-number-of-diracs" aria-label="Permalink to &quot;Scaling with the number of diracs&quot;">​</a></h2><p>The number of Newton iterations barely depends on <code>n</code> (5 iterations and 6 diagrams for a uniform cloud at 1e5 and 1e6). The total cost therefore follows the cost of one diagram plus one linear solve, which are both close to linear in <code>n</code>.</p><table tabindex="0"><thead><tr><th>dim</th><th>n</th><th>GPU, mixed</th><th>time per dirac</th></tr></thead><tbody><tr><td>2D</td><td>1e5</td><td>0.073 s (A6000)</td><td>0.73 µs</td></tr><tr><td>2D</td><td>1e6</td><td>0.383 s (A6000)</td><td>0.38 µs</td></tr><tr><td>2D</td><td>1e7</td><td>8.4 s eager (2080 Ti, 6.6 GB)</td><td>0.84 µs</td></tr><tr><td>3D</td><td>1e5</td><td>0.135 s (A6000)</td><td>1.35 µs</td></tr><tr><td>3D</td><td>1e6</td><td>1.31 s (A6000)</td><td>1.31 µs</td></tr><tr><td>3D</td><td>1e7</td><td>55 s eager (A6000)</td><td>5.5 µs</td></tr></tbody></table><p>At 1e7 diracs in 3D, the float kernel can no longer resolve the cells (each cell is about 4.6e-3 wide in a unit box), so the solve switches to the double kernel. On cards with slow FP64 this switch costs half of the total time.</p><p>GPU memory is about 900 bytes per dirac in 2D and 1300 in 3D at 1e6. A solve that does not fit raises a <code>MemoryError</code> before it starts.</p><h2 id="scaling-with-the-dimension" tabindex="-1">Scaling with the dimension <a class="header-anchor" href="#scaling-with-the-dimension" aria-label="Permalink to &quot;Scaling with the dimension&quot;">​</a></h2><p>Lebesgue on the unit hypercube, diracs drawn uniformly, a cold start, <code>rtol = 1e-6</code>. CPU <code>1</code>, 8 pinned threads, double kernel, <code>step = trials</code>. One run per row (3 for 4D at 1e5). 6D at 1e3: 9 min (5 / 7).</p><table tabindex="0"><thead><tr><th>dim</th><th>total, n = 1e4</th><th>Newton it. / diagrams</th><th>one diagram, per dirac (n = 1e4)</th><th>vertices per cell</th></tr></thead><tbody><tr><td>2</td><td>0.20 s</td><td>5 / 6</td><td>0.9 µs</td><td>6</td></tr><tr><td>3</td><td>0.40 s</td><td>5 / 6</td><td>3.6 µs</td><td>~25</td></tr><tr><td>4</td><td>5.1 s</td><td>5 / 6</td><td>80 µs</td><td>~120</td></tr><tr><td>5</td><td>103 s</td><td>5 / 6</td><td>1.7 ms</td><td>~670</td></tr><tr><td>6</td><td>52 min</td><td>4 / 5</td><td>63 ms</td><td>~3300</td></tr></tbody></table><p>Newton is not affected by the dimension: the iteration count (5 iterations, 6 diagrams) and the cost of the linear solves (under 2.5 s at 1e5) stay the same up to 6D. The whole cost is in the cells. A Laguerre cell of a uniform cloud has a number of vertices that grows very fast with <code>d</code> (the last column, averaged over a few thousand diracs), and the cell is cut, measured and triangulated vertex by vertex. Each added dimension multiplies the cost of a diagram by about 20 (3D to 4D, 4D to 5D), then by about 40 from 5D to 6D.</p><p>In practice, 4D is comfortable up to a few 10⁵ diracs and 5D up to about 10⁵. 6D is limited to about 10⁴ diracs (an hour on 8 cores). Beyond that, the cost comes from the geometry of the cells, not from the solver.</p>',24)])])}const b=e(o,[["render",s]]);export{u as __pageData,b as default};
